'use strict';
function continuitySnapshot(o,s,at){const v=stateAt(o,at),copy=structuredClone(o);copy.id=uid();copy.locked=false;copy.hidden=false;copy.keys=[{t:0,v:{...v}}];delete copy.in;delete copy.out;for(const key of ['actionBlocks','motionPath','footPins','bodyAnimation','expressionKeys','speechTrackId','lookTargetId','pointTargetId','exitTransition','dialogueLineId'])delete copy[key];copy.characterLoop='none';copy.storyVoiceEnabled=false;copy.lipSync=false;copy.expression=isAnimatedCharacter(o)?expressionAt(o,at):copy.expression;if(copy.explainerAsset){copy.explainerAsset.motion='still';if(copy.explainerAsset.style==='vector'){copy.objectAnimation=Object.fromEntries(Object.keys(partDefinitions(o)).map(field=>[field,[{t:0,value:clamp(objectPartValue(o,field,at),partDefinitions(o)[field][1],partDefinitions(o)[field][2]),ease:'hold'}]]));copy.explainerAsset.details=false}}return copy}
function carrySceneContinuity({actorId,targetId='new',at=current().duration,position=true,pose:copyPose=true,appearance=true,props=true}={}){stop();const source=current(),actor=source.objects.find(o=>o.id===actorId)||object();if(!isAnimatedCharacter(actor)||actor.locked)throw Error('Choose an unlocked character to continue.');at=clamp(at,clipStart(actor),clipEnd(actor,source));let target=project.scenes.find(s=>s.id===targetId);if(targetId!=='new'&&!target)throw Error('Choose an existing target scene.');if(target===source)throw Error('Choose a different scene.');const fresh=!target;if(fresh){if(project.scenes.length>=99)throw Error('Keep fewer than 100 scenes.');target=scene('After '+source.name,source.bg,source.template);target.duration=source.duration;target.backgroundImage=source.backgroundImage;target.backgroundFit=source.backgroundFit}const sources=[actor,...(props?heldProps(source,actor.id,at).map(a=>a.prop):[])],sourceLinks=new Map(sources.map(o=>[o.id,o.continuityId||uid()])),copies=[],mapping=new Map(),replaced=[];for(const original of sources){const link=sourceLinks.get(original.id),existing=target.objects.find(o=>o.continuityId===link);if(existing?.locked)throw Error('Unlock the linked '+existing.name+' in the target scene first.');let copy=continuitySnapshot(original,source,at);if(existing){if(copy.type!==existing.type)throw Error('The linked object type changed. Use a new scene.');if(!appearance){const savedKeys=copy.keys;copy=structuredClone(existing);copy.keys=savedKeys;for(const key of ['actionBlocks','motionPath','footPins','bodyAnimation','expressionKeys','speechTrackId','lookTargetId','pointTargetId','exitTransition'])delete copy[key];copy.characterLoop='none'}if(!position){const v=stateAt(existing,0);for(const k of ['x','y','scale','rotation','opacity'])copy.keys[0].v[k]=v[k]}if(!copyPose&&isAnimatedCharacter(original)){const v=stateAt(existing,0);for(const k of Object.keys(v))if(!['x','y','scale','rotation','opacity'].includes(k))copy.keys[0].v[k]=v[k]}copy.id=existing.id;replaced.push(existing.id)}else if(!position){copy.keys[0].v.x=480;copy.keys[0].v.y=isAnimatedCharacter(copy)?440:290}copy.continuityId=link;copy.continuitySource={sceneId:source.id,objectId:original.id,at};copies.push(copy);mapping.set(original.id,copy.id)}if(target.objects.length-replaced.length+copies.length>=500)throw Error('The target scene has too many layers.');const holds=[];if(props)for(const {prop,event}of heldProps(source,actor.id,at)){const owner=propEventOwner(event,at);holds.push({...structuredClone(event),id:uid(),kind:'hold',actorId:mapping.get(actor.id),propId:mapping.get(prop.id),otherId:null,hand:owner.hand,start:0,duration:Math.min(1,target.duration),fromPose:stateAt(prop,at),actorStartPose:structuredClone(copies.find(o=>o.id===mapping.get(actor.id)).keys[0].v),otherStartPose:null})}const anchors=sceneAudioAnchors();for(const original of sources)original.continuityId=sourceLinks.get(original.id);if(fresh)project.scenes.splice(project.scenes.indexOf(source)+1,0,target);target.objects=target.objects.filter(o=>!replaced.includes(o.id));target.objects.push(...copies);target.propInteractions=(target.propInteractions||[]).filter(i=>![i.actorId,i.propId,i.otherId].some(id=>replaced.includes(id)));target.propInteractions.push(...holds);placeSceneAudio(anchors);normalizeLinkedMedia();sceneIndex=project.scenes.indexOf(target);time=0;selectLayers([mapping.get(actor.id)]);save();render();return{scene:target,objects:copies,held:holds}}
document.querySelector('.studio-toolbar').insertAdjacentHTML('beforeend','<button id="openSceneContinuity">Continue into next scene</button>');
document.body.insertAdjacentHTML('beforeend',`<dialog id="sceneContinuityDialog"><div class="tool-heading"><div><div class="eyebrow">KEEP THE STORY CONNECTED</div><h2>Continue into another scene</h2></div><button id="closeSceneContinuity">Close</button></div><label>Character<select id="continuityActor"></select></label><label>Capture<select id="continuityMoment"><option value="end">Scene end</option><option value="playhead">Current playhead</option></select></label><label>Target<select id="continuityTarget"></select></label><div class="continuity-options"><label><input id="continuityPosition" type="checkbox" checked> Position & size</label><label><input id="continuityPose" type="checkbox" checked> Pose</label><label><input id="continuityAppearance" type="checkbox" checked> Appearance</label><label><input id="continuityProps" type="checkbox" checked> Held objects</label></div><p class="note">Create linked copies with their captured pose. Future transfers update the same linked copies. Their previous animation is replaced; Undo restores it. Dialogue and voice clips stay in their original scenes.</p><p id="continuityStatus" role="status" class="note"></p><button id="applySceneContinuity" class="primary">Continue scene</button></dialog>`);
function openSceneContinuity(){stop();const actors=storyActors(current());if(!actors.length)return toast('Add a character first.');$('continuityActor').replaceChildren();for(const o of actors){const option=document.createElement('option');option.value=o.id;option.textContent=o.name;$('continuityActor').append(option)}if(isAnimatedCharacter(object()))$('continuityActor').value=object().id;const target=$('continuityTarget');target.innerHTML='<option value="new">Create next scene</option>';for(const s of project.scenes.filter(s=>s!==current())){const option=document.createElement('option');option.value=s.id;option.textContent=s.name;target.append(option)}$('continuityStatus').textContent='';$('sceneContinuityDialog').showModal()}
$('openSceneContinuity').onclick=openSceneContinuity;$('closeSceneContinuity').onclick=()=>$('sceneContinuityDialog').close();$('applySceneContinuity').onclick=()=>{try{const result=carrySceneContinuity({actorId:$('continuityActor').value,targetId:$('continuityTarget').value,at:$('continuityMoment').value==='end'?current().duration:time,position:$('continuityPosition').checked,pose:$('continuityPose').checked,appearance:$('continuityAppearance').checked,props:$('continuityProps').checked});$('sceneContinuityDialog').close();toast('Continued '+result.objects.length+' linked layers, including '+result.held.length+' held objects.')}catch(e){$('continuityStatus').textContent=e.message}};
const controlsBeforeContinuity=renderControls;renderControls=function(){controlsBeforeContinuity();if(!isAnimatedCharacter(object()))return;const b=storyButton('Continue into next scene',openSceneContinuity);b.id='continueSelectedCharacter';b.disabled=!!object().locked;$('walkCharacterTo')?.closest('details')?.append(b)};
const remapBeforeContinuity=remapStoryReferences;remapStoryReferences=function(copy,objects,audio,scenes){remapBeforeContinuity(copy,objects,audio,scenes);const links=new Map();for(const s of copy.scenes)for(const o of s.objects){if(o.continuityId){if(!links.has(o.continuityId))links.set(o.continuityId,uid());o.continuityId=links.get(o.continuityId)}if(o.continuitySource){o.continuitySource.sceneId=scenes.get(o.continuitySource.sceneId)||o.continuitySource.sceneId;o.continuitySource.objectId=objects.get(o.continuitySource.objectId)||o.continuitySource.objectId}}};
const duplicationBeforeContinuity=$('duplicate').onclick;$('duplicate').onclick=()=>{const originals=selectedLayers(),before=new Set(current().objects.map(o=>o.id)),events=structuredClone(current().propInteractions||[]);duplicationBeforeContinuity();const copies=current().objects.filter(o=>!before.has(o.id)),map=new Map(originals.map((o,i)=>[o.id,copies[i]?.id]));let changed=false;for(const o of copies)if(o.continuityId){delete o.continuityId;delete o.continuitySource;changed=true}for(const old of events)if(map.get(old.actorId)&&map.get(old.propId)&&(old.kind!=='handover'||map.get(old.otherId))){const copy=structuredClone(old);copy.id=uid();for(const key of ['actorId','propId','otherId'])if(copy[key])copy[key]=map.get(copy[key]);copy.fromPose.x+=35;(current().propInteractions??=[]).push(copy);changed=true}if(changed){historyStack.pop();save();render()}};
const validBeforeContinuity=valid;valid=function(p){return validBeforeContinuity(p)&&p.scenes.every(s=>s.objects.every(o=>(o.continuityId===undefined||typeof o.continuityId==='string'&&o.continuityId.length<=100)&&(!o.continuitySource||typeof o.continuitySource.sceneId==='string'&&typeof o.continuitySource.objectId==='string'&&Number.isFinite(o.continuitySource.at))))};
render();
